{
  "required" : [ "deviation", "height", "import_key", "plant_distance", "row_distance", "row_number", "speed", "timestamp" ],
  "type" : "object",
  "properties" : {
    "id" : {
      "type" : "integer",
      "description" : "The numeric ID of the Plant",
      "format" : "int64",
      "example" : 4711
    },
